import { arrayToMap } from "@excalidraw/common";

import { isBoundToContainer } from "./typeChecks";

import type { ElementsMap, ExcalidrawElement } from "./types";

/** `customData` key holding the id of the client that created the element */
export const CREATOR_ID_KEY = "creatorId";

/**
 * `customData` key holding the ids of the clients that edited an element they
 * didn't create (co-owners). The element follows the least restrictive
 * visibility/lock setting among its creator and co-owners.
 */
export const EDITOR_IDS_KEY = "editorIds";

/**
 * `customData` key holding, per client that ever co-owned the element, a
 * counter bumped each time that client is added or removed. It turns the
 * co-owner list into a mergeable set: every client only ever changes its own
 * entry, so when copies disagree the higher counter is the newer state. Ids
 * listed here but not in `editorIds` were removed (kept so a stale copy can't
 * bring them back).
 */
export const EDITOR_SEQS_KEY = "editorSeqs";

/** bucket for elements without (valid) creator metadata, e.g. legacy rooms */
export const UNKNOWN_CREATOR_ID = "__unknown__";

const getStampedCreatorId = (element: ExcalidrawElement): string | null => {
  const creatorId = element.customData?.[CREATOR_ID_KEY];
  return typeof creatorId === "string" && creatorId ? creatorId : null;
};

/** the element's current co-owners: valid, de-duplicated ids */
export const getStampedEditorIds = (element: ExcalidrawElement): string[] => {
  const editorIds = element.customData?.[EDITOR_IDS_KEY];
  if (!Array.isArray(editorIds)) {
    return [];
  }
  return [
    ...new Set(
      editorIds.filter(
        (id: unknown): id is string => typeof id === "string" && !!id,
      ),
    ),
  ];
};

/** the element holding `element`'s ownership (bound text → its container) */
const getOwnershipHolder = (
  element: ExcalidrawElement,
  elementsMap: ElementsMap,
): ExcalidrawElement =>
  isBoundToContainer(element)
    ? elementsMap.get(element.containerId) ?? element
    : element;

/**
 * Returns the id of the client that created the element, or
 * `UNKNOWN_CREATOR_ID` if it isn't known.
 *
 * Bound text follows its container so labels never show/hide separately
 * from the shape they belong to.
 */
export const getElementCreatorId = (
  element: ExcalidrawElement,
  elementsMap: ElementsMap,
): string =>
  getStampedCreatorId(getOwnershipHolder(element, elementsMap)) ??
  UNKNOWN_CREATOR_ID;

/**
 * Every owner of the element: its creator (or `UNKNOWN_CREATOR_ID` if not
 * known) followed by its co-owners. Bound text follows its container.
 */
export const getElementOwnerIds = (
  element: ExcalidrawElement,
  elementsMap: ElementsMap,
): string[] => {
  const holder = getOwnershipHolder(element, elementsMap);
  return [
    ...new Set([
      getStampedCreatorId(holder) ?? UNKNOWN_CREATOR_ID,
      ...getStampedEditorIds(holder),
    ]),
  ];
};

/** structurally satisfied by the editor's AppState */
export type CreatorVisibility = {
  /**
   * creator ids hidden on this client. `UNKNOWN_CREATOR_ID` hides the
   * miscellaneous bucket.
   */
  hiddenCollaboratorIds?: ReadonlySet<string>;
  /**
   * creators this client can name (seen at some point). Stamped creators
   * missing from it are treated as unknown (miscellaneous). `null`/omitted
   * (e.g. outside of a room) → every stamped creator is its own bucket.
   */
  collaboratorDirectory?: ReadonlyMap<string, unknown> | null;
};

/** an owner's bucket: `UNKNOWN_CREATOR_ID` if this client never saw them */
const toVisibilityBucket = (
  ownerId: string,
  collaboratorDirectory: CreatorVisibility["collaboratorDirectory"],
): string =>
  collaboratorDirectory &&
  ownerId !== UNKNOWN_CREATOR_ID &&
  !collaboratorDirectory.has(ownerId)
    ? UNKNOWN_CREATOR_ID
    : ownerId;

/**
 * The visibility bucket of the element's creator: the creator, or
 * `UNKNOWN_CREATOR_ID` for untagged elements and creators this client has
 * never seen. Ignores co-owners; see `getElementVisibilityBuckets`.
 */
export const getElementVisibilityBucket = (
  element: ExcalidrawElement,
  elementsMap: ElementsMap,
  collaboratorDirectory: CreatorVisibility["collaboratorDirectory"],
): string =>
  toVisibilityBucket(
    getElementCreatorId(element, elementsMap),
    collaboratorDirectory,
  );

/**
 * Every visibility bucket the element belongs to: its creator's and each
 * co-owner's (de-duplicated, so several unknown owners share one bucket).
 */
export const getElementVisibilityBuckets = (
  element: ExcalidrawElement,
  elementsMap: ElementsMap,
  collaboratorDirectory: CreatorVisibility["collaboratorDirectory"],
): string[] => [
  ...new Set(
    getElementOwnerIds(element, elementsMap).map((ownerId) =>
      toVisibilityBucket(ownerId, collaboratorDirectory),
    ),
  ),
];

/**
 * Whether the element is hidden: only when EVERY one of its visibility
 * buckets is hidden (it follows its least restricted owner).
 *
 * Element-level counterpart of the editor's `isElementHiddenLocally`, so
 * element logic (selection, binding) can exclude hidden collaborators'
 * elements without depending on the editor package.
 */
export const isElementByHiddenCreator = (
  element: ExcalidrawElement,
  elementsMap: ElementsMap,
  { hiddenCollaboratorIds, collaboratorDirectory }: CreatorVisibility,
): boolean => {
  if (!hiddenCollaboratorIds?.size) {
    return false;
  }
  return getElementVisibilityBuckets(
    element,
    elementsMap,
    collaboratorDirectory,
  ).every((bucketId) => hiddenCollaboratorIds.has(bucketId));
};

/** structurally satisfied by the editor's AppState */
export type CreatorInteractivity = CreatorVisibility & {
  /**
   * creator ids locked on this client (visible but non-interactive).
   * `UNKNOWN_CREATOR_ID` locks the miscellaneous bucket.
   */
  lockedCollaboratorIds?: ReadonlySet<string>;
};

/**
 * The interactivity rule (#81): whether this client may interact with a
 * visibility bucket's elements.
 *
 * - hidden → never interactive (no interactivity without visibility)
 * - your own bucket → can't be locked
 * - otherwise → interactive unless locked
 */
export const isCollaboratorInteractive = (
  bucketId: string,
  { hiddenCollaboratorIds, lockedCollaboratorIds }: CreatorInteractivity,
  selfId: string | null,
): boolean => {
  if (hiddenCollaboratorIds?.has(bucketId)) {
    return false;
  }
  if (bucketId === selfId) {
    return true;
  }
  return !lockedCollaboratorIds?.has(bucketId);
};

/** returns the lock list with `ids` added, never including yourself */
export const addLockedCollaborators = (
  lockedCollaboratorIds: ReadonlySet<string> | undefined,
  ids: Iterable<string>,
  selfId: string | null,
): Set<string> => {
  const next = new Set(lockedCollaboratorIds);
  for (const id of ids) {
    if (id !== selfId) {
      next.add(id);
    }
  }
  return next;
};

/**
 * Returns the lock list with `bucketId` toggled. Ignored for hidden buckets
 * (their lock can't change while hidden) and for yourself.
 */
export const toggleLockedCollaborator = (
  state: CreatorInteractivity,
  bucketId: string,
  selfId: string | null,
): Set<string> => {
  const next = new Set(state.lockedCollaboratorIds);
  if (bucketId === selfId || state.hiddenCollaboratorIds?.has(bucketId)) {
    return next;
  }
  if (!next.delete(bucketId)) {
    next.add(bucketId);
  }
  return next;
};

/**
 * Returns the lock list after "unlock all": every visible bucket is
 * unlocked, hidden ones stay locked (so they're still locked once shown).
 */
export const unlockVisibleCollaborators = (
  { hiddenCollaboratorIds }: CreatorInteractivity,
  selfId: string | null,
): Set<string> =>
  addLockedCollaborators(undefined, hiddenCollaboratorIds ?? [], selfId);

/** structurally satisfied by the editor's AppState */
export type CreatorSelf = {
  collaborators?: ReadonlyMap<
    unknown,
    Readonly<{ id?: string; isCurrentUser?: boolean }>
  >;
};

/** this client's creator id (the current user's collaborator entry), if any */
export const getSelfCreatorId = ({
  collaborators,
}: CreatorSelf): string | null => {
  for (const collaborator of collaborators?.values() ?? []) {
    if (collaborator.isCurrentUser && collaborator.id) {
      return collaborator.id;
    }
  }
  return null;
};

/**
 * Whether this client may interact with the element (select, move, resize,
 * rotate, delete, erase, text-edit): when ANY of its visibility buckets is
 * interactive per `isCollaboratorInteractive`, i.e. it follows its least
 * restricted owner. Elements whose buckets are all hidden never are.
 *
 * @param selfId defaults to the current user's id from `state.collaborators`;
 * pass it when checking many elements.
 */
export const isElementInteractive = (
  element: ExcalidrawElement,
  elementsMap: ElementsMap,
  state: CreatorInteractivity & CreatorSelf,
  selfId: string | null = getSelfCreatorId(state),
): boolean =>
  getElementVisibilityBuckets(
    element,
    elementsMap,
    state.collaboratorDirectory,
  ).some((bucketId) => isCollaboratorInteractive(bucketId, state, selfId));

/**
 * Filters out elements this client may not interact with (hidden or locked
 * collaborators'). Returns the input array as-is when nobody is hidden or
 * locked.
 *
 * @param elementsMap used to resolve bound text containers. Defaults to a map
 * of `elements`, so pass the full scene map when `elements` is a subset.
 */
export const excludeNonInteractiveElements = <T extends ExcalidrawElement>(
  elements: readonly T[],
  state: CreatorInteractivity & CreatorSelf,
  elementsMap?: ElementsMap,
): readonly T[] => {
  if (
    !state.hiddenCollaboratorIds?.size &&
    !state.lockedCollaboratorIds?.size
  ) {
    return elements;
  }
  const map = elementsMap ?? arrayToMap(elements);
  const selfId = getSelfCreatorId(state);
  return elements.filter((element) =>
    isElementInteractive(element, map, state, selfId),
  );
};

/** structurally satisfied by the editor's AppState */
export type CreatorLayering = CreatorVisibility &
  CreatorSelf & {
    /** layering on → elements are drawn in `collaboratorLayerOrder` */
    collaboratorLayeringEnabled?: boolean;
    /**
     * local layer order of visibility buckets, top row (drawn on top) first.
     * `null`/omitted → the default order.
     */
    collaboratorLayerOrder?: readonly string[] | null;
  };

/**
 * The layer order used when layering is first turned on, and on reset (#82):
 * you on top, then everyone in join order, the miscellaneous bucket last.
 *
 * Join order is the order of `collaboratorDirectory` (#116), which records
 * each collaborator the first time this client sees them (a `Map` keeps
 * insertion order). Live collaborators not recorded yet follow it.
 */
export const getDefaultCollaboratorLayerOrder = (
  state: CreatorVisibility & CreatorSelf,
): string[] => {
  const order = new Set<string>();
  const selfId = getSelfCreatorId(state);
  if (selfId) {
    order.add(selfId);
  }
  for (const id of state.collaboratorDirectory?.keys() ?? []) {
    order.add(id);
  }
  for (const collaborator of state.collaborators?.values() ?? []) {
    if (collaborator.id) {
      order.add(collaborator.id);
    }
  }
  order.add(UNKNOWN_CREATOR_ID);
  return [...order];
};

/**
 * The layer order shown in the dropdown and used for drawing (#82): the
 * stored order (or the default one), with anyone not in it yet added to the
 * bottom in join order. Ids are never dropped, so collaborators who are
 * hidden or left keep their place.
 */
export const getCollaboratorLayerOrder = (
  state: CreatorLayering,
): readonly string[] => {
  const defaultOrder = getDefaultCollaboratorLayerOrder(state);
  const stored = state.collaboratorLayerOrder;
  if (!stored) {
    return defaultOrder;
  }
  const known = new Set(stored);
  const newcomers = defaultOrder.filter((id) => !known.has(id));
  return newcomers.length ? [...stored, ...newcomers] : stored;
};

/**
 * Returns `order` with `id` moved to `toIndex` (clamped to the list), or
 * `order` itself when nothing changes (unknown id, or already there).
 */
export const moveCollaboratorLayer = (
  order: readonly string[],
  id: string,
  toIndex: number,
): readonly string[] => {
  const fromIndex = order.indexOf(id);
  const targetIndex = Math.min(Math.max(toIndex, 0), order.length - 1);
  if (fromIndex === -1 || fromIndex === targetIndex) {
    return order;
  }
  const next = order.filter((other) => other !== id);
  next.splice(targetIndex, 0, id);
  return next;
};

/**
 * The single layering rule (#82), used for rendering, hit-testing, binding
 * and export: while layering is on, elements of a higher collaborator in the
 * layer order are drawn after (above) every element of a lower one. The sort
 * is stable, so each collaborator keeps the shared drawing order. Bound text
 * follows its container's owners. Buckets missing from the order go below
 * everyone.
 *
 * A co-owned element (#84) is drawn in the layer of its highest VISIBLE
 * owner, like it follows its least restricted owner for visibility and
 * locking. If every owner is hidden (it isn't drawn then), its highest owner
 * is used.
 *
 * Never changes elements (their shared `index` stays as is). Returns the
 * input array as-is while layering is off.
 *
 * @param elementsMap used to resolve bound text containers. Defaults to a map
 * of `elements`, so pass the full scene map when `elements` is a subset.
 */
export const orderElementsByCollaboratorLayer = <T extends ExcalidrawElement>(
  elements: readonly T[],
  state: CreatorLayering,
  elementsMap?: ElementsMap,
): readonly T[] => {
  if (!state.collaboratorLayeringEnabled) {
    return elements;
  }
  const order = getCollaboratorLayerOrder(state);
  // higher rank = drawn later (on top); missing buckets rank lowest (-1)
  const rankByBucket = new Map(
    order.map((id, index) => [id, order.length - 1 - index]),
  );
  const map = elementsMap ?? arrayToMap(elements);
  const getRank = (element: T) => {
    const buckets = getElementVisibilityBuckets(
      element,
      map,
      state.collaboratorDirectory,
    );
    const visibleBuckets = buckets.filter(
      (bucket) => !state.hiddenCollaboratorIds?.has(bucket),
    );
    return Math.max(
      ...(visibleBuckets.length ? visibleBuckets : buckets).map(
        (bucket) => rankByBucket.get(bucket) ?? -1,
      ),
    );
  };
  return elements
    .map((element) => ({ element, rank: getRank(element) }))
    .sort((a, b) => a.rank - b.rank)
    .map(({ element }) => element);
};

/**
 * Filters out elements whose visibility bucket is hidden. Returns the input
 * array as-is when nothing is hidden.
 *
 * @param elementsMap used to resolve bound text containers. Defaults to a map
 * of `elements`, so pass the full scene map when `elements` is a subset.
 */
export const excludeElementsByHiddenCreators = <T extends ExcalidrawElement>(
  elements: readonly T[],
  visibility: CreatorVisibility,
  elementsMap?: ElementsMap,
): readonly T[] => {
  if (!visibility.hiddenCollaboratorIds?.size) {
    return elements;
  }
  const map = elementsMap ?? arrayToMap(elements);
  return elements.filter(
    (element) => !isElementByHiddenCreator(element, map, visibility),
  );
};

// -----------------------------------------------------------------------------
// co-ownership: editing someone else's element makes you a co-owner
// -----------------------------------------------------------------------------

/**
 * Element properties whose change doesn't count as editing the element:
 * bookkeeping, z-order, and references updated as a side effect of editing
 * other elements (e.g. binding an arrow updates the shape's `boundElements`).
 */
const NON_EDIT_PROPS: ReadonlySet<string> = new Set([
  "version",
  "versionNonce",
  "updated",
  "seed",
  "index",
  "boundElements",
  "customData",
]);

const isSameValue = (a: unknown, b: unknown) =>
  a === b ||
  (typeof a === "object" &&
    typeof b === "object" &&
    a !== null &&
    b !== null &&
    JSON.stringify(a) === JSON.stringify(b));

/** whether going from `prev` to `next` edits the element (see NON_EDIT_PROPS) */
export const isOwnershipEdit = (
  prev: ExcalidrawElement,
  next: ExcalidrawElement,
): boolean => {
  for (const key of new Set([...Object.keys(prev), ...Object.keys(next)])) {
    if (
      !NON_EDIT_PROPS.has(key) &&
      !isSameValue(
        prev[key as keyof ExcalidrawElement],
        next[key as keyof ExcalidrawElement],
      )
    ) {
      return true;
    }
  }
  return false;
};

/** structurally satisfied by the editor's AppState */
export type CoOwnershipEditState = CreatorSelf & {
  selectedElementIds: Readonly<Record<string, true>>;
  editingTextElement?: Readonly<{ id: string }> | null;
  selectedLinearElement?: Readonly<{ elementId: string }> | null;
};

/**
 * Whether the user acted on the element directly: it (or the shape a label
 * belongs to) is selected, being text-edited, or having its points edited.
 * Elements changed as a side effect (an arrow rerouted because the shape it's
 * bound to moved, a dragged frame's children…) don't count.
 */
const isDirectlyEdited = (
  element: ExcalidrawElement,
  holder: ExcalidrawElement,
  state: CoOwnershipEditState,
): boolean =>
  !!state.selectedElementIds[element.id] ||
  !!state.selectedElementIds[holder.id] ||
  state.editingTextElement?.id === element.id ||
  state.selectedLinearElement?.elementId === element.id;

/** whether `clientId` is the element's creator or one of its co-owners */
export const isElementOwnedBy = (
  element: ExcalidrawElement,
  clientId: string,
): boolean =>
  getStampedCreatorId(element) === clientId ||
  getStampedEditorIds(element).includes(clientId);

/**
 * Elements this client edited without owning them, so it becomes a co-owner.
 * Compares the scene against the last committed snapshot, so it's meant to
 * run right before a change is captured into history (the stamp then lands in
 * the same undo entry as the edit, and undoing that edit removes it).
 *
 * Returns the elements holding the ownership (bound text → its container),
 * de-duplicated. Only elements that already existed and carry a creator stamp
 * qualify: new elements get the creator stamp, not a co-owner stamp.
 */
export const getElementsToCoOwn = (
  prevElements: ElementsMap,
  nextElements: ElementsMap,
  state: CoOwnershipEditState,
  selfId: string | null = getSelfCreatorId(state),
): ExcalidrawElement[] => {
  if (!selfId) {
    return [];
  }

  const toCoOwn = new Map<string, ExcalidrawElement>();
  for (const next of nextElements.values()) {
    const prev = prevElements.get(next.id);
    if (!prev || prev.version >= next.version || next.isDeleted) {
      continue;
    }
    const holder = getOwnershipHolder(next, nextElements);
    if (
      holder.isDeleted ||
      toCoOwn.has(holder.id) ||
      !getStampedCreatorId(holder) ||
      isElementOwnedBy(holder, selfId) ||
      !isDirectlyEdited(next, holder, state) ||
      !isOwnershipEdit(prev, next)
    ) {
      continue;
    }
    toCoOwn.set(holder.id, holder);
  }
  return [...toCoOwn.values()];
};

// -----------------------------------------------------------------------------
// the co-owner set: one entry per client, changed only by that client
// -----------------------------------------------------------------------------

type CustomData = NonNullable<ExcalidrawElement["customData"]>;

/** one client's co-ownership: `seq` increases with every add / remove */
type EditorEntry = Readonly<{ seq: number; present: boolean }>;

const isValidSeq = (seq: unknown): seq is number =>
  typeof seq === "number" && Number.isFinite(seq) && seq >= 0;

/**
 * Reads the co-owner entries. Co-owners without a counter (data from before
 * counters existed) get 0, the oldest possible state.
 */
const readEditorEntries = (
  element: ExcalidrawElement,
): Map<string, EditorEntry> => {
  const raw = element.customData?.[EDITOR_SEQS_KEY];
  const seqs: Record<string, unknown> =
    raw && typeof raw === "object" && !Array.isArray(raw) ? raw : {};
  const seqOf = (id: string) => (isValidSeq(seqs[id]) ? seqs[id] : 0);

  const entries = new Map<string, EditorEntry>();
  for (const id of getStampedEditorIds(element)) {
    entries.set(id, { seq: seqOf(id), present: true });
  }
  for (const id of Object.keys(seqs)) {
    if (id && !entries.has(id) && isValidSeq(seqs[id])) {
      entries.set(id, { seq: seqs[id] as number, present: false });
    }
  }
  return entries;
};

/** `customData` with the co-owner keys replaced by `entries` (sorted ids) */
const writeEditorEntries = (
  customData: ExcalidrawElement["customData"],
  entries: ReadonlyMap<string, EditorEntry>,
): CustomData => {
  const {
    [EDITOR_IDS_KEY]: _editorIds,
    [EDITOR_SEQS_KEY]: _editorSeqs,
    ...rest
  } = customData ?? {};
  if (!entries.size) {
    return rest;
  }
  const ids = [...entries.keys()].sort();
  return {
    ...rest,
    [EDITOR_IDS_KEY]: ids.filter((id) => entries.get(id)!.present),
    [EDITOR_SEQS_KEY]: Object.fromEntries(
      ids.map((id) => [id, entries.get(id)!.seq]),
    ),
  };
};

const isSameEntries = (
  a: ReadonlyMap<string, EditorEntry>,
  b: ReadonlyMap<string, EditorEntry>,
) =>
  a.size === b.size &&
  [...a].every(([id, entry]) => {
    const other = b.get(id);
    return other?.seq === entry.seq && other.present === entry.present;
  });

/** the element's `customData` with `clientId` added as a co-owner */
export const getCoOwnedCustomData = (
  element: ExcalidrawElement,
  clientId: string,
): CustomData => {
  const entries = readEditorEntries(element);
  entries.set(clientId, {
    seq: (entries.get(clientId)?.seq ?? 0) + 1,
    present: true,
  });
  return writeEditorEntries(element.customData, entries);
};

/**
 * Merges the co-owners of two copies of the same element, e.g. when
 * collaboration picks one copy over another. Per client, the entry with the
 * higher counter wins (it's newer, since only that client changes it); on a
 * tie (only possible with old data), being a co-owner wins.
 *
 * Commutative, associative and idempotent, so every client converges to the
 * same co-owners whatever order copies arrive in.
 *
 * Returns `winner`'s `customData` with the merged co-owners, or `null` if
 * the merge wouldn't change `winner`'s.
 */
export const mergeCoOwnership = (
  winner: ExcalidrawElement,
  other: ExcalidrawElement,
): CustomData | null => {
  const winnerEntries = readEditorEntries(winner);
  const merged = new Map(winnerEntries);
  for (const [id, entry] of readEditorEntries(other)) {
    const current = merged.get(id);
    if (
      !current ||
      entry.seq > current.seq ||
      (entry.seq === current.seq && entry.present && !current.present)
    ) {
      merged.set(id, entry);
    }
  }
  return isSameEntries(merged, winnerEntries)
    ? null
    : writeEditorEntries(winner.customData, merged);
};

/**
 * Undo/redo restores an element's whole `customData`, which would also undo
 * co-ownership that other clients gained in the meantime. Only this client's
 * own co-ownership follows history (with a new, higher counter, so the
 * change wins against older copies); everyone else's stays as it was right
 * before the undo/redo.
 *
 * Returns the `customData` to use instead of `applied`'s, or `null` if
 * `applied`'s is already right.
 */
export const reconcileEditorIdsAfterHistory = (
  beforeHistory: ExcalidrawElement,
  applied: ExcalidrawElement,
  selfId: string | null,
): CustomData | null => {
  const beforeEntries = readEditorEntries(beforeHistory);
  const appliedEntries = readEditorEntries(applied);
  const next = new Map(beforeEntries);

  if (selfId) {
    const before = beforeEntries.get(selfId);
    const after = appliedEntries.get(selfId);
    const isPresent = !!after?.present;
    if (!!before?.present !== isPresent) {
      next.set(selfId, {
        seq: Math.max(before?.seq ?? 0, after?.seq ?? 0) + 1,
        present: isPresent,
      });
    }
  }

  return isSameEntries(next, appliedEntries)
    ? null
    : writeEditorEntries(applied.customData, next);
};

mutants.replacement:
element.isDeleted &&
// labels count as part of their shape
element.type === "text" && element.containerId

packages/excalidraw/scene/visibility.ts.source:
import { arrayToMap } from "@excalidraw/common";
import {
  UNKNOWN_CREATOR_ID,
  excludeElementsByHiddenCreators,
  getElementVisibilityBuckets,
  getElementsInGroup,
  getSelfCreatorId,
  isCollaboratorInteractive,
  isElementByHiddenCreator,
  isElementInteractive,
} from "@excalidraw/element";

import type { ElementsMap, ExcalidrawElement } from "@excalidraw/element/types";

import type { AppState } from "../types";

export type LocalVisibilityState = Pick<
  AppState,
  "hiddenCollaboratorIds" | "collaboratorDirectory"
>;

/**
 * Whether the element is hidden on this client by the collaborator
 * visibility controls. Purely a local view filter — scene data is untouched.
 *
 * Creators missing from `collaboratorDirectory` (never seen by this client)
 * share the miscellaneous bucket with untagged elements.
 */
export const isElementHiddenLocally = (
  element: ExcalidrawElement,
  elementsMap: ElementsMap,
  appState: LocalVisibilityState,
): boolean => isElementByHiddenCreator(element, elementsMap, appState);

export type LocalInteractivityState = LocalVisibilityState &
  Partial<Pick<AppState, "lockedCollaboratorIds" | "collaborators">>;

/**
 * Whether this client may interact with the element (#81): not hidden and
 * not locked by the collaborator controls. See `isCollaboratorInteractive`.
 */
export const isElementInteractiveLocally = (
  element: ExcalidrawElement,
  elementsMap: ElementsMap,
  appState: LocalInteractivityState,
): boolean => isElementInteractive(element, elementsMap, appState);

/**
 * Returns only the elements visible on this client (e.g. for export).
 * Returns the input array as-is when nothing is hidden.
 *
 * @param elementsMap used to resolve bound text containers. Defaults to
 * a map of `elements`, so pass the full scene map when `elements` is a subset.
 */
export const getLocallyVisibleElements = <T extends ExcalidrawElement>(
  elements: readonly T[],
  appState: LocalVisibilityState,
  elementsMap?: ElementsMap,
): readonly T[] =>
  excludeElementsByHiddenCreators(elements, appState, elementsMap);

/**
 * Selection safety net: hidden or locked (non-interactive) elements must
 * never stay selected, otherwise actions (delete, ungroup, move…) would
 * modify them for every collaborator.
 *
 * Returns the selection-related appState to apply, or `null` if the
 * selection contains no non-interactive elements.
 */
export const getSelectionWithoutHiddenElements = (
  appState: LocalInteractivityState &
    Pick<
      AppState,
      "selectedElementIds" | "selectedGroupIds" | "selectedLinearElement"
    >,
  elementsMap: ElementsMap,
): Pick<
  AppState,
  "selectedElementIds" | "selectedGroupIds" | "selectedLinearElement"
> | null => {
  if (
    !appState.hiddenCollaboratorIds.size &&
    !appState.lockedCollaboratorIds?.size
  ) {
    return null;
  }

  const selfId = getSelfCreatorId(appState);
  // (named `isHidden` since #116; covers locked elements too since #81)
  const isHidden = (id: string) => {
    const element = elementsMap.get(id);
    return (
      !!element && !isElementInteractive(element, elementsMap, appState, selfId)
    );
  };

  const hiddenSelectedIds = Object.keys(appState.selectedElementIds).filter(
    isHidden,
  );
  // a group containing hidden members can't stay selected as a group, or
  // group actions (ungroup, group bbox…) would reach the hidden members
  const groupIdsWithHiddenMembers = Object.keys(
    appState.selectedGroupIds,
  ).filter((groupId) =>
    getElementsInGroup(elementsMap, groupId).some((el) => isHidden(el.id)),
  );
  const isLinearElementHidden =
    !!appState.selectedLinearElement &&
    isHidden(appState.selectedLinearElement.elementId);

  if (
    !hiddenSelectedIds.length &&
    !groupIdsWithHiddenMembers.length &&
    !isLinearElementHidden
  ) {
    return null;
  }

  const selectedElementIds = { ...appState.selectedElementIds };
  for (const id of hiddenSelectedIds) {
    delete selectedElementIds[id];
  }

  const selectedGroupIds = { ...appState.selectedGroupIds };
  for (const groupId of groupIdsWithHiddenMembers) {
    delete selectedGroupIds[groupId];
  }

  return {
    selectedElementIds,
    selectedGroupIds,
    selectedLinearElement: isLinearElementHidden
      ? null
      : appState.selectedLinearElement,
  };
};

/** this client's creator id (set by the host app on the current user's entry) */
export const getSelfCollaboratorId = (
  appState: Pick<AppState, "collaborators">,
): string | null => getSelfCreatorId(appState);

/**
 * Whether the user hid their own drawings. Anything they'd draw would be
 * hidden immediately, so the editor is locked to view mode meanwhile.
 */
export const isOwnDrawingsHidden = (
  appState: Pick<AppState, "collaborators" | "hiddenCollaboratorIds">,
): boolean => {
  const selfId = getSelfCollaboratorId(appState);
  return !!selfId && appState.hiddenCollaboratorIds.has(selfId);
};

/**
 * Every visibility bucket currently known on this client: live
 * collaborators, previously seen ones, creators of the scene's elements and
 * the miscellaneous bucket. "Hide all" hides all of these.
 */
export const getVisibilityBuckets = (
  elements: readonly ExcalidrawElement[],
  appState: Pick<AppState, "collaborators" | "collaboratorDirectory">,
): Set<string> => {
  const buckets = new Set<string>([UNKNOWN_CREATOR_ID]);

  for (const collaborator of appState.collaborators.values()) {
    if (collaborator.id) {
      buckets.add(collaborator.id);
    }
  }
  for (const clientId of appState.collaboratorDirectory?.keys() ?? []) {
    buckets.add(clientId);
  }

  const elementsMap = arrayToMap(elements);
  for (const element of elements) {
    if (!element.isDeleted) {
      // co-owners too, or "Hide all" would leave co-owned elements visible
      for (const bucket of getElementVisibilityBuckets(
        element,
        elementsMap,
        appState.collaboratorDirectory,
      )) {
        buckets.add(bucket);
      }
    }
  }

  return buckets;
};

export type CollaboratorVisibilityRow = {
  /** visibility bucket id (client id, or UNKNOWN_CREATOR_ID) */
  id: string;
  username: string | null;
  isCurrentUser: boolean;
  isHidden: boolean;
  /** shown as locked: non-interactive (always true while hidden) */
  isLocked: boolean;
  /** the lock can't be changed: hidden, or your own row */
  isLockDisabled: boolean;
  /**
   * non-deleted elements in this bucket (bound text counts with its shape;
   * a co-owned element counts for each of its owners)
   */
  drawingsCount: number;
  avatarUrl?: string;
};

export type CollaboratorVisibilityRows = {
  inRoom: CollaboratorVisibilityRow[];
  previouslySeen: CollaboratorVisibilityRow[];
  miscellaneous: CollaboratorVisibilityRow;
};

/** a row while layering is on, labelled with its #116 section */
export type CollaboratorLayerRow = CollaboratorVisibilityRow & {
  section: keyof CollaboratorVisibilityRows;
};

/**
 * The rows while layering is on (#82): a single list in layer order (top
 * row = drawn on top), each row keeping its #116 section as a label.
 *
 * @param order the layer order, see `getCollaboratorLayerOrder`
 */
export const getCollaboratorLayerRows = (
  { inRoom, previouslySeen, miscellaneous }: CollaboratorVisibilityRows,
  order: readonly string[],
): CollaboratorLayerRow[] => {
  const rowsById = new Map<string, CollaboratorLayerRow>();
  for (const row of inRoom) {
    rowsById.set(row.id, { ...row, section: "inRoom" });
  }
  for (const row of previouslySeen) {
    rowsById.set(row.id, { ...row, section: "previouslySeen" });
  }
  rowsById.set(miscellaneous.id, {
    ...miscellaneous,
    section: "miscellaneous",
  });
  return order.flatMap((id) => rowsById.get(id) ?? []);
};

/**
 * Whether "Lock all" / "Unlock all" would change anything (#81). Only rows
 * whose lock can change count: hidden collaborators (always locked) and
 * your own row (never locked) are skipped, so after "Hide all" neither
 * button applies.
 */
export const getBulkLockAvailability = ({
  inRoom,
  previouslySeen,
  miscellaneous,
}: CollaboratorVisibilityRows): {
  canLockAll: boolean;
  canUnlockAll: boolean;
} => {
  const changeable = [...inRoom, ...previouslySeen, miscellaneous].filter(
    (row) => !row.isLockDisabled,
  );
  return {
    canLockAll: changeable.some((row) => !row.isLocked),
    canUnlockAll: changeable.some((row) => row.isLocked),
  };
};

/**
 * Rows for the collaborator visibility menu:
 * - in the room: live collaborators (you first)
 * - previously seen: directory entries no longer live (most recent first)
 * - miscellaneous: untagged elements + creators this client never saw
 */
export const getCollaboratorVisibilityRows = (
  elements: readonly ExcalidrawElement[],
  appState: Pick<
    AppState,
    "collaborators" | "collaboratorDirectory" | "hiddenCollaboratorIds"
  > &
    Partial<Pick<AppState, "lockedCollaboratorIds">>,
): CollaboratorVisibilityRows => {
  const elementsMap = arrayToMap(elements);
  const selfId = getSelfCollaboratorId(appState);
  const counts = new Map<string, number>();
  for (const element of elements) {
    if (
      element.isDeleted ||
      // labels count as part of their shape
      (element.type === "text" && element.containerId)
    ) {
      continue;
    }
    // a co-owned element counts for each of its owners
    for (const bucket of getElementVisibilityBuckets(
      element,
      elementsMap,
      appState.collaboratorDirectory,
    )) {
      counts.set(bucket, (counts.get(bucket) ?? 0) + 1);
    }
  }

  const toRow = (
    id: string,
    username: string | null,
    extra?: Partial<CollaboratorVisibilityRow>,
  ): CollaboratorVisibilityRow => ({
    id,
    username,
    isCurrentUser: false,
    isHidden: appState.hiddenCollaboratorIds.has(id),
    isLocked: !isCollaboratorInteractive(id, appState, selfId),
    isLockDisabled: id === selfId || appState.hiddenCollaboratorIds.has(id),
    drawingsCount: counts.get(id) ?? 0,
    ...extra,
  });

  const inRoom = new Map<string, CollaboratorVisibilityRow>();
  for (const collaborator of appState.collaborators.values()) {
    // several tabs can't share an id, but guard against duplicates anyway
    if (collaborator.id && !inRoom.has(collaborator.id)) {
      inRoom.set(
        collaborator.id,
        toRow(
          collaborator.id,
          collaborator.username ??
            appState.collaboratorDirectory?.get(collaborator.id)?.username ??
            null,
          {
            isCurrentUser: !!collaborator.isCurrentUser,
            avatarUrl: collaborator.avatarUrl,
          },
        ),
      );
    }
  }

  const previouslySeen = [...(appState.collaboratorDirectory ?? [])]
    .filter(([id]) => !inRoom.has(id))
    .sort(([, a], [, b]) => b.lastSeen - a.lastSeen)
    .map(([id, entry]) => toRow(id, entry.username));

  return {
    inRoom: [...inRoom.values()].sort(
      (a, b) =>
        Number(b.isCurrentUser) - Number(a.isCurrentUser) ||
        (a.username ?? "").localeCompare(b.username ?? ""),
    ),
    previouslySeen,
    miscellaneous: toRow(UNKNOWN_CREATOR_ID, null),
  };
};

packages/excalidraw/tests/collaboratorVi.source:
import { CLASSES, CODES, KEYS, setFeatureFlag } from "@excalidraw/common";
import {
  CREATOR_ID_KEY,
  UNKNOWN_CREATOR_ID,
  LinearElementEditor,
  handleFocusPointDrag,
  newElementWith,
  selectGroupsForSelectedElements,
} from "@excalidraw/element";
import { vi } from "vitest";

import type {
  ExcalidrawArrowElement,
  ExcalidrawElement,
  NonDeleted,
} from "@excalidraw/element/types";

import {
  actionHideAllCollaborators,
  actionSaveFileToDisk,
  actionShowAllCollaborators,
  actionToggleCollaboratorVisibility,
} from "../actions";
import { actionToggleViewMode } from "../actions/actionToggleViewMode";
import { prepareElementsForExport } from "../data";
import { Excalidraw } from "../index";
import {
  getCollaboratorVisibilityRows,
  getLocallyVisibleElements,
  getSelectionWithoutHiddenElements,
} from "../scene/visibility";

import { API } from "./helpers/api";
import { Keyboard, Pointer, UI } from "./helpers/ui";
import { updateTextEditor } from "./queries/dom";
import {
  act,
  fireEvent,
  mockBoundingClientRect,
  render,
  restoreOriginalGetBoundingClientRect,
  unmountComponent,
  waitFor,
} from "./test-utils";

import type { AppState } from "../types";

unmountComponent();

// same as excalidraw.test.tsx: no real file is written when saving
vi.mock("../data/filesystem.ts", async (importOriginal) => {
  const module = await importOriginal();
  return {
    __esmodule: true,
    //@ts-ignore
    ...module,
    get nativeFileSystemSupported() {
      //@ts-ignore
      return module.nativeFileSystemSupported;
    },
    fileSave: vi.fn().mockResolvedValue(undefined),
  };
});

const h = window.h;
const mouse = new Pointer("mouse");

const stamp = <T extends ExcalidrawElement>(element: T, creatorId: string) =>
  newElementWith(element as ExcalidrawElement, {
    customData: { [CREATOR_ID_KEY]: creatorId },
  }) as T;

// the jsdom viewport is 0x0, so query the renderer with an explicit viewport
// (same approach as frame.test.tsx)
const getVisibleIds = () =>
  h.app.renderer
    .getRenderableElements({
      zoom: h.state.zoom,
      offsetLeft: 0,
      offsetTop: 0,
      scrollX: 0,
      scrollY: 0,
      height: 1000,
      width: 1000,
      editingTextElement: h.state.editingTextElement,
      newElement: h.state.newElement,
      selectedElements: [],
      selectedElementsAreBeingDragged: false,
      frameToHighlight: null,
      hiddenCollaboratorIds: h.state.hiddenCollaboratorIds,
      collaboratorDirectory: h.state.collaboratorDirectory,
    })
    .visibleElements.map((el) => el.id)
    .sort();

const setHidden = (ids: string[]) => {
  act(() => {
    API.setAppState({ hiddenCollaboratorIds: new Set(ids) });
  });
};

const createRect = (id: string, x: number) =>
  API.createElement({ type: "rectangle", id, x, y: 0, width: 10 });

describe("collaborator visibility (rendering)", () => {
  const aliceRect = stamp(createRect("alice-rect", 0), "alice");
  const bobRect = stamp(createRect("bob-rect", 20), "bob");
  const legacyRect = createRect("legacy-rect", 40);

  beforeEach(async () => {
    await render(<Excalidraw />);
    API.setElements([aliceRect, bobRect, legacyRect]);
  });

  it("renders everything by default", () => {
    expect(h.state.hiddenCollaboratorIds.size).toBe(0);
    expect(getVisibleIds()).toEqual(["alice-rect", "bob-rect", "legacy-rect"]);
  });

  it("hides only the hidden collaborator's elements", () => {
    setHidden(["bob"]);
    expect(getVisibleIds()).toEqual(["alice-rect", "legacy-rect"]);
  });

  it("re-renders hidden elements when shown again", () => {
    setHidden(["bob"]);
    setHidden([]);
    expect(getVisibleIds()).toEqual(["alice-rect", "bob-rect", "legacy-rect"]);
  });

  it("hides untagged elements via the unknown bucket", () => {
    setHidden([UNKNOWN_CREATOR_ID]);
    expect(getVisibleIds()).toEqual(["alice-rect", "bob-rect"]);
  });

  it("does not modify scene data when hiding", () => {
    const before = h.elements.map((el) => ({
      id: el.id,
      version: el.version,
      versionNonce: el.versionNonce,
      isDeleted: el.isDeleted,
    }));

    setHidden(["alice", "bob", UNKNOWN_CREATOR_ID]);

    expect(getVisibleIds()).toEqual([]);
    expect(
      h.elements.map((el) => ({
        id: el.id,
        version: el.version,
        versionNonce: el.versionNonce,
        isDeleted: el.isDeleted,
      })),
    ).toEqual(before);
  });

  it("bound text is hidden together with its container", () => {
    const container = stamp(createRect("container", 0), "bob");
    const label = stamp(
      API.createElement({
        type: "text",
        id: "label",
        x: 2,
        y: 2,
        containerId: container.id,
      }),
      "alice",
    );
    API.setElements([container, label]);

    setHidden(["bob"]);
    expect(getVisibleIds()).toEqual([]);

    setHidden(["alice"]);
    expect(getVisibleIds()).toEqual(["container", "label"]);
  });

  it("hides frame names (DOM) together with the frame", () => {
    const frame = stamp(
      API.createElement({ type: "frame", id: "frame", x: 0, y: 0, width: 50 }),
      "bob",
    );
    API.setElements([frame]);

    const getFrameNames = () =>
      document.querySelectorAll(`.${CLASSES.FRAME_NAME}`);

    expect(getFrameNames().length).toBe(1);

    setHidden(["bob"]);
    expect(getFrameNames().length).toBe(0);

    setHidden([]);
    expect(getFrameNames().length).toBe(1);
  });

  it("is never persisted or exported", async () => {
    const { clearAppStateForLocalStorage, cleanAppStateForExport } =
      await import("../appState");

    setHidden(["bob"]);

    expect(clearAppStateForLocalStorage(h.state)).not.toHaveProperty(
      "hiddenCollaboratorIds",
    );
    expect(cleanAppStateForExport(h.state)).not.toHaveProperty(
      "hiddenCollaboratorIds",
    );
  });
});

describe("collaborator visibility (interaction safety)", () => {
  // solid fill so clicking the interior counts as a hit
  const createSolidRect = (id: string, x: number, groupIds: string[] = []) =>
    API.createElement({
      type: "rectangle",
      id,
      x,
      y: 0,
      width: 100,
      height: 100,
      backgroundColor: "red",
      fillStyle: "solid",
      groupIds,
    });

  const isDeleted = (id: string) =>
    h.elements.find((el) => el.id === id)!.isDeleted;

  const getSelectedIds = () =>
    API.getSelectedElements()
      .map((el) => el.id)
      .sort();

  beforeEach(async () => {
    await render(<Excalidraw handleKeyboardGlobally={true} />);
    API.setElements([
      stamp(createSolidRect("alice-rect", 0), "alice"),
      stamp(createSolidRect("bob-rect", 200), "bob"),
    ]);
  });

  it("clicking a hidden element doesn't select it", () => {
    setHidden(["bob"]);

    mouse.clickAt(250, 50);
    expect(getSelectedIds()).toEqual([]);

    mouse.clickAt(50, 50);
    expect(getSelectedIds()).toEqual(["alice-rect"]);
  });

  // same gesture as selection.test.tsx (intermediate move past the drag threshold)
  const boxSelectBoth = () => {
    mouse.downAt(-50, -50);
    mouse.move(-1000, -1000);
    mouse.moveTo(350, 150);
    mouse.up();
  };

  it("(control) box-selecting selects all covered elements", () => {
    boxSelectBoth();
    expect(getSelectedIds()).toEqual(["alice-rect", "bob-rect"]);
  });

  it("box-selecting skips hidden elements", () => {
    setHidden(["bob"]);

    boxSelectBoth();
    expect(getSelectedIds()).toEqual(["alice-rect"]);
  });

  it("select all + delete never deletes hidden elements", () => {
    setHidden(["bob"]);

    Keyboard.withModifierKeys({ ctrl: true }, () => {
      Keyboard.keyPress(KEYS.A);
    });
    expect(getSelectedIds()).toEqual(["alice-rect"]);

    Keyboard.keyPress(KEYS.DELETE);
    expect(isDeleted("alice-rect")).toBe(true);
    expect(isDeleted("bob-rect")).toBe(false);
  });

  it("hiding a selected element deselects it", () => {
    API.setSelectedElements([...h.app.scene.getNonDeletedElements()]);
    expect(getSelectedIds()).toEqual(["alice-rect", "bob-rect"]);

    setHidden(["bob"]);
    expect(getSelectedIds()).toEqual(["alice-rect"]);
  });

  describe("mixed-collaborator groups", () => {
    beforeEach(() => {
      API.setElements([
        stamp(createSolidRect("alice-rect", 0, ["group"]), "alice"),
        stamp(createSolidRect("bob-rect", 200, ["group"]), "bob"),
      ]);
    });

    it("selecting a visible member never selects hidden members", () => {
      setHidden(["bob"]);

      mouse.clickAt(50, 50);
      expect(getSelectedIds()).toEqual(["alice-rect"]);
      expect(h.state.selectedGroupIds).not.toHaveProperty("group");

      Keyboard.keyPress(KEYS.DELETE);
      expect(isDeleted("alice-rect")).toBe(true);
      expect(isDeleted("bob-rect")).toBe(false);
    });

    const eraseThroughAliceRect = () => {
      UI.clickTool("eraser");
      mouse.downAt(-20, 50);
      mouse.moveTo(20, 50);
      mouse.moveTo(60, 50);
      mouse.upAt(60, 50);
    };

    it("(control) erasing a member erases the whole group", () => {
      eraseThroughAliceRect();
      expect(isDeleted("alice-rect")).toBe(true);
      expect(isDeleted("bob-rect")).toBe(true);
    });

    it("erasing a visible member never erases hidden members", () => {
      setHidden(["bob"]);

      eraseThroughAliceRect();
      expect(isDeleted("alice-rect")).toBe(true);
      expect(isDeleted("bob-rect")).toBe(false);
    });
  });
});

describe("collaborator visibility (export)", () => {
  const aliceRect = stamp(createRect("alice-rect", 0), "alice");
  const bobRect = stamp(createRect("bob-rect", 20), "bob");

  beforeEach(async () => {
    await render(<Excalidraw />);
    API.setElements([aliceRect, bobRect]);
  });

  const getExportedIds = (exportSelectionOnly = false) =>
    prepareElementsForExport(h.elements, h.state, exportSelectionOnly)
      .exportedElements.map((el) => el.id)
      .sort();

  it("exports everything when nothing is hidden", () => {
    expect(getExportedIds()).toEqual(["alice-rect", "bob-rect"]);
  });

  it("exports only visible elements", () => {
    setHidden(["bob"]);
    expect(getExportedIds()).toEqual(["alice-rect"]);
  });

  it("export follows the current visibility", () => {
    setHidden(["bob"]);
    expect(getExportedIds()).toEqual(["alice-rect"]);

    setHidden(["alice"]);
    expect(getExportedIds()).toEqual(["bob-rect"]);
  });

  it("getLocallyVisibleElements returns the same array when nothing is hidden", () => {
    const elements = h.elements;
    expect(getLocallyVisibleElements(elements, h.state)).toBe(elements);
  });
});

describe("collaborator visibility (chokepoints)", () => {
  // solid fill so pointer hits/bindings work on the interior
  const createSolidRect = (id: string, x: number, groupIds: string[] = []) =>
    API.createElement({
      type: "rectangle",
      id,
      x,
      y: 0,
      width: 100,
      height: 100,
      backgroundColor: "red",
      fillStyle: "solid",
      groupIds,
    });

  const getArrow = () =>
    h.elements.find(
      (el): el is ExcalidrawArrowElement =>
        el.type === "arrow" && !el.isDeleted,
    )!;

  const drawArrowFromAliceToBob = () => {
    UI.clickTool("arrow");
    mouse.downAt(50, 50);
    mouse.moveTo(200, 50);
    mouse.moveTo(350, 50);
    mouse.upAt(350, 50);
  };

  beforeEach(async () => {
    await render(<Excalidraw handleKeyboardGlobally={true} />);
    API.setElements([
      stamp(createSolidRect("alice-rect", 0), "alice"),
      stamp(createSolidRect("bob-rect", 300), "bob"),
    ]);
  });

  afterEach(() => {
    mouse.reset();
  });

  describe("selection (selectGroupsForSelectedElements)", () => {
    it("never returns hidden elements, even without the App safety net", () => {
      API.setElements([
        stamp(createSolidRect("alice-rect", 0, ["group"]), "alice"),
        stamp(createSolidRect("bob-rect", 300, ["group"]), "bob"),
      ]);
      setHidden(["bob"]);

      const result = selectGroupsForSelectedElements(
        {
          selectedElementIds: { "alice-rect": true, "bob-rect": true },
          editingGroupId: null,
        },
        h.app.scene.getNonDeletedElements(),
        h.state,
        null,
      );

      expect(Object.keys(result.selectedElementIds)).toEqual(["alice-rect"]);
      // with its hidden member excluded the group has a single member, so it
      // isn't selected as a group
      expect(result.selectedGroupIds.group).toBeFalsy();
    });

    it("(control) selects the whole group when nothing is hidden", () => {
      API.setElements([
        stamp(createSolidRect("alice-rect", 0, ["group"]), "alice"),
        stamp(createSolidRect("bob-rect", 300, ["group"]), "bob"),
      ]);

      const result = selectGroupsForSelectedElements(
        { selectedElementIds: { "alice-rect": true }, editingGroupId: null },
        h.app.scene.getNonDeletedElements(),
        h.state,
        null,
      );

      expect(Object.keys(result.selectedElementIds).sort()).toEqual([
        "alice-rect",
        "bob-rect",
      ]);
      expect(result.selectedGroupIds.group).toBe(true);
    });
  });

  describe("arrow binding", () => {
    it("(control) a new arrow binds to both shapes", () => {
      drawArrowFromAliceToBob();

      expect(getArrow().startBinding?.elementId).toBe("alice-rect");
      expect(getArrow().endBinding?.elementId).toBe("bob-rect");
    });

    it("a new arrow can't bind to a hidden shape", () => {
      setHidden(["bob"]);
      drawArrowFromAliceToBob();

      expect(getArrow().startBinding?.elementId).toBe("alice-rect");
      expect(getArrow().endBinding).toBeNull();
      // and the hidden shape's data is untouched
      expect(
        h.elements.find((el) => el.id === "bob-rect")!.boundElements ?? [],
      ).toEqual([]);
    });

    it("existing bindings to a hidden shape are kept", () => {
      drawArrowFromAliceToBob();
      expect(getArrow().endBinding?.elementId).toBe("bob-rect");

      setHidden(["bob"]);

      // move the visible, bound shape
      UI.clickTool("selection");
      mouse.downAt(50, 80);
      mouse.moveTo(50, 130);
      mouse.moveTo(50, 180);
      mouse.upAt(50, 180);

      expect(getArrow().startBinding?.elementId).toBe("alice-rect");
      expect(getArrow().endBinding?.elementId).toBe("bob-rect");
    });
  });
});

describe("collaborator visibility (miscellaneous bucket)", () => {
