/**
 * Co-ownership: editing someone else's element makes you a co-owner, and the
 * element follows its least restricted owner's visibility / lock setting.
 */
import { arrayToMap } from "@excalidraw/common";

import { newElement, newTextElement } from "../newElement";
import { newElementWith } from "../mutateElement";
import {
  CREATOR_ID_KEY,
  EDITOR_IDS_KEY,
  EDITOR_SEQS_KEY,
  UNKNOWN_CREATOR_ID,
  getCoOwnedCustomData,
  mergeCoOwnership,
  getElementOwnerIds,
  getElementVisibilityBuckets,
  getElementsToCoOwn,
  isElementByHiddenCreator,
  isElementInteractive,
  isOwnershipEdit,
  reconcileEditorIdsAfterHistory,
} from "../ownership";

import type { ExcalidrawElement } from "../types";

const createRect = (
  creatorId?: string,
  editorIds?: unknown,
  editorSeqs?: Record<string, number>,
) =>
  newElement({
    type: "rectangle",
    x: 0,
    y: 0,
    customData: {
      ...(creatorId === undefined ? {} : { [CREATOR_ID_KEY]: creatorId }),
      ...(editorIds === undefined ? {} : { [EDITOR_IDS_KEY]: editorIds }),
      ...(editorSeqs === undefined ? {} : { [EDITOR_SEQS_KEY]: editorSeqs }),
    },
  });

/** co-owners and their counters, as written to `customData` */
const editors = (
  customData: ExcalidrawElement["customData"] | null | undefined,
) => ({
  ids: customData?.[EDITOR_IDS_KEY],
  seqs: customData?.[EDITOR_SEQS_KEY],
});

const state = (hidden: string[] = [], locked: string[] = []) => ({
  hiddenCollaboratorIds: new Set(hidden),
  lockedCollaboratorIds: new Set(locked),
  collaborators: new Map([
    ["alice-socket", { id: "alice", isCurrentUser: true }],
  ]),
});

describe("owners and buckets", () => {
  it("lists the creator first, then co-owners, without duplicates", () => {
    const rect = createRect("bob", ["carol", "bob", "carol", 42, ""]);
    expect(getElementOwnerIds(rect, arrayToMap([rect]))).toEqual([
      "bob",
      "carol",
    ]);
  });

  it("an untagged element edited by someone is owned by unknown + them", () => {
    const rect = createRect(undefined, ["carol"]);
    expect(getElementOwnerIds(rect, arrayToMap([rect]))).toEqual([
      UNKNOWN_CREATOR_ID,
      "carol",
    ]);
  });

  it("bound text follows its container's owners", () => {
    const container = createRect("bob", ["carol"]);
    const text = newTextElement({
      text: "label",
      x: 0,
      y: 0,
      containerId: container.id,
    });
    expect(getElementOwnerIds(text, arrayToMap([container, text]))).toEqual([
      "bob",
      "carol",
    ]);
  });

  it("owners this client never saw share the miscellaneous bucket", () => {
    const rect = createRect("bob", ["dave", "erin"]);
    const directory = new Map([["bob", {}]]);
    expect(
      getElementVisibilityBuckets(rect, arrayToMap([rect]), directory),
    ).toEqual(["bob", UNKNOWN_CREATOR_ID]);
  });
});

describe("least restricted owner rule", () => {
  // the example from the feature request: Alice has Bob locked but not
  // Carol, and Carol edited Bob's element
  const rect = createRect("bob", ["carol"]);
  const map = arrayToMap([rect]);

  it("Bob locked, Carol not → interactive for Alice", () => {
    expect(isElementInteractive(rect, map, state([], ["bob"]))).toBe(true);
  });

  it("Bob and Carol both locked → not interactive", () => {
    expect(isElementInteractive(rect, map, state([], ["bob", "carol"]))).toBe(
      false,
    );
  });

  it("Bob hidden, Carol visible → visible and interactive", () => {
    expect(isElementByHiddenCreator(rect, map, state(["bob"]))).toBe(false);
    expect(isElementInteractive(rect, map, state(["bob"], ["bob"]))).toBe(true);
  });

  it("Bob hidden, Carol locked → visible but not interactive", () => {
    expect(isElementByHiddenCreator(rect, map, state(["bob"]))).toBe(false);
    expect(
      isElementInteractive(rect, map, state(["bob"], ["bob", "carol"])),
    ).toBe(false);
  });

  it("Bob and Carol both hidden → hidden and not interactive", () => {
    expect(isElementByHiddenCreator(rect, map, state(["bob", "carol"]))).toBe(
      true,
    );
    expect(isElementInteractive(rect, map, state(["bob", "carol"]))).toBe(
      false,
    );
  });

  it("an element I co-own can't be locked for me", () => {
    const mine = createRect("bob", ["alice"]);
    expect(
      isElementInteractive(mine, arrayToMap([mine]), state([], ["bob"])),
    ).toBe(true);
  });

  it("without co-owners the creator alone decides (unchanged behaviour)", () => {
    const bobs = createRect("bob");
    expect(
      isElementInteractive(bobs, arrayToMap([bobs]), state([], ["bob"])),
    ).toBe(false);
    expect(
      isElementByHiddenCreator(bobs, arrayToMap([bobs]), state(["bob"])),
    ).toBe(true);
  });
});

describe("isOwnershipEdit", () => {
  const rect = createRect("bob");

  it("moving or restyling is an edit", () => {
    expect(isOwnershipEdit(rect, newElementWith(rect, { x: 5 }))).toBe(true);
    expect(
      isOwnershipEdit(rect, newElementWith(rect, { strokeColor: "#f00" })),
    ).toBe(true);
  });

  it("bookkeeping, z-order and binding references are not", () => {
    expect(
      isOwnershipEdit(
        rect,
        newElementWith(rect, {
          index: "a5" as any,
          boundElements: [{ id: "arrow", type: "arrow" }],
          customData: { foo: 1 },
        }),
      ),
    ).toBe(false);
  });

  it("deep-equal copies (like store snapshots) are not edits", () => {
    const line = newElement({ type: "rectangle", x: 0, y: 0 });
    const copy = { ...line, groupIds: [...line.groupIds] };
    expect(isOwnershipEdit(line, copy as ExcalidrawElement)).toBe(false);
  });
});

describe("getElementsToCoOwn", () => {
  const appState = (selected: string[]) => ({
    selectedElementIds: Object.fromEntries(
      selected.map((id) => [id, true as const]),
    ),
    collaborators: new Map([["me-socket", { id: "me", isCurrentUser: true }]]),
  });

  const edit = (element: ExcalidrawElement) =>
    newElementWith(element, { x: element.x + 10 });

  it("a selected, edited element someone else created gets me as co-owner", () => {
    const rect = createRect("bob");
    const result = getElementsToCoOwn(
      arrayToMap([rect]),
      arrayToMap([edit(rect)]),
      appState([rect.id]),
    );
    expect(result.map((el) => el.id)).toEqual([rect.id]);
  });

  it("an element changed as a side effect (not selected) doesn't", () => {
    const rect = createRect("bob");
    expect(
      getElementsToCoOwn(
        arrayToMap([rect]),
        arrayToMap([edit(rect)]),
        appState([]),
      ),
    ).toEqual([]);
  });

  it("elements I already own don't", () => {
    const mine = createRect("me");
    const coOwned = createRect("bob", ["me"]);
    expect(
      getElementsToCoOwn(
        arrayToMap([mine, coOwned]),
        arrayToMap([edit(mine), edit(coOwned)]),
        appState([mine.id, coOwned.id]),
      ),
    ).toEqual([]);
  });

  it("new, deleted, unstamped or merely re-indexed elements don't", () => {
    const fresh = createRect("bob");
    const deleted = createRect("bob");
    const untagged = createRect();
    const reindexed = createRect("bob");
    expect(
      getElementsToCoOwn(
        arrayToMap([deleted, untagged, reindexed]),
        arrayToMap([
          fresh,
          newElementWith(deleted as ExcalidrawElement, { isDeleted: true }),
          edit(untagged),
          newElementWith(reindexed, { index: "a9" as any }),
        ]),
        appState([fresh.id, deleted.id, untagged.id, reindexed.id]),
      ),
    ).toEqual([]);
  });

  it("editing a label co-owns its shape", () => {
    const container = createRect("bob");
    const text = newTextElement({
      text: "label",
      x: 0,
      y: 0,
      containerId: container.id,
    });
    const result = getElementsToCoOwn(
      arrayToMap([container, text]),
      arrayToMap([container, newElementWith(text, { text: "edited" })]),
      { ...appState([]), editingTextElement: text },
    );
    expect(result.map((el) => el.id)).toEqual([container.id]);
  });

  it("does nothing outside of a room (no self id)", () => {
    const rect = createRect("bob");
    expect(
      getElementsToCoOwn(arrayToMap([rect]), arrayToMap([edit(rect)]), {
        selectedElementIds: { [rect.id]: true },
      }),
    ).toEqual([]);
  });

  it("getCoOwnedCustomData adds me with a new counter and keeps other custom data", () => {
    const rect = newElementWith(createRect("bob", ["carol"]), {
      customData: {
        [CREATOR_ID_KEY]: "bob",
        [EDITOR_IDS_KEY]: ["carol"],
        [EDITOR_SEQS_KEY]: { carol: 1, me: 2 },
        x: 1,
      },
    });
    expect(getCoOwnedCustomData(rect, "me")).toEqual({
      [CREATOR_ID_KEY]: "bob",
      [EDITOR_IDS_KEY]: ["carol", "me"],
      // my old entry (removed at 2) is superseded by a newer one
      [EDITOR_SEQS_KEY]: { carol: 1, me: 3 },
      x: 1,
    });
  });
});

describe("mergeCoOwnership", () => {
  it("keeps concurrent co-owners from both copies", () => {
    const carolsCopy = createRect("bob", ["carol"], { carol: 1 });
    const davesCopy = createRect("bob", ["dave"], { dave: 1 });
    expect(editors(mergeCoOwnership(carolsCopy, davesCopy))).toEqual({
      ids: ["carol", "dave"],
      seqs: { carol: 1, dave: 1 },
    });
  });

  it("a newer removal beats an older copy that still lists the co-owner", () => {
    const removed = createRect("bob", [], { me: 2 });
    const stale = createRect("bob", ["me"], { me: 1 });
    expect(mergeCoOwnership(removed, stale)).toBeNull();
    expect(editors(mergeCoOwnership(stale, removed))).toEqual({
      ids: [],
      seqs: { me: 2 },
    });
  });

  it("a newer re-add beats an older removal", () => {
    const readded = createRect("bob", ["me"], { me: 3 });
    const removed = createRect("bob", [], { me: 2 });
    expect(editors(mergeCoOwnership(removed, readded))).toEqual({
      ids: ["me"],
      seqs: { me: 3 },
    });
  });

  it("is commutative: both orders give the same co-owners", () => {
    const a = createRect("bob", ["carol", "me"], { carol: 4, me: 1, dave: 2 });
    const b = createRect("bob", ["dave"], { carol: 5, me: 1, dave: 3 });
    const ab = mergeCoOwnership(a, b);
    const ba = mergeCoOwnership(b, a) ?? b.customData;
    expect(editors(ab)).toEqual(editors(ba));
    expect(editors(ab)).toEqual({
      ids: ["dave", "me"],
      seqs: { carol: 5, dave: 3, me: 1 },
    });
  });

  it("keeps the winner's other custom data", () => {
    const winner = newElementWith(createRect("bob"), {
      customData: { [CREATOR_ID_KEY]: "bob", note: "winner" },
    });
    const other = createRect("alice", ["carol"], { carol: 1 });
    expect(mergeCoOwnership(winner, other)).toEqual({
      [CREATOR_ID_KEY]: "bob",
      note: "winner",
      [EDITOR_IDS_KEY]: ["carol"],
      [EDITOR_SEQS_KEY]: { carol: 1 },
    });
  });

  it("returns null when the winner already has everything", () => {
    const winner = createRect("bob", ["carol"], { carol: 2 });
    const other = createRect("bob", ["carol"], { carol: 1 });
    expect(mergeCoOwnership(winner, other)).toBeNull();
  });

  it("old data without counters: being a co-owner wins the tie", () => {
    const withCarol = createRect("bob", ["carol"]);
    const withoutCarol = createRect("bob");
    expect(editors(mergeCoOwnership(withoutCarol, withCarol)).ids).toEqual([
      "carol",
    ]);
  });
});

describe("reconcileEditorIdsAfterHistory", () => {
  it("undo removes me (with a newer counter) but keeps co-owners added meanwhile", () => {
    const before = createRect("bob", ["carol", "me"], { carol: 1, me: 1 });
    const applied = createRect("bob");
    expect(
      editors(reconcileEditorIdsAfterHistory(before, applied, "me")),
    ).toEqual({ ids: ["carol"], seqs: { carol: 1, me: 2 } });
  });

  it("redo adds me back (with a newer counter) and keeps everyone else", () => {
    const before = createRect("bob", ["carol"], { carol: 1, me: 2 });
    const applied = createRect("bob", ["me"], { me: 1 });
    expect(
      editors(reconcileEditorIdsAfterHistory(before, applied, "me")),
    ).toEqual({ ids: ["carol", "me"], seqs: { carol: 1, me: 3 } });
  });

  it("history can't bring back someone else who had been removed", () => {
    const before = createRect("bob", [], { carol: 2 });
    const applied = createRect("bob", ["carol"], { carol: 1 });
    expect(
      editors(reconcileEditorIdsAfterHistory(before, applied, "me")),
    ).toEqual({ ids: [], seqs: { carol: 2 } });
  });

  it("keeps the applied element's other custom data", () => {
    const before = createRect("bob", ["me"], { me: 1 });
    const applied = newElementWith(createRect("bob"), {
      customData: { [CREATOR_ID_KEY]: "bob", note: "restored" },
    });
    expect(reconcileEditorIdsAfterHistory(before, applied, "me")).toEqual({
      [CREATOR_ID_KEY]: "bob",
      note: "restored",
      [EDITOR_IDS_KEY]: [],
      [EDITOR_SEQS_KEY]: { me: 2 },
    });
  });

  it("returns null when history already got it right", () => {
    const before = createRect("bob", ["carol"], { carol: 1 });
    const applied = createRect("bob", ["carol"], { carol: 1 });
    expect(reconcileEditorIdsAfterHistory(before, applied, "me")).toBeNull();
  });
});

packages/excalidraw/tests/coOwnership.te.source:
/**
 * Co-ownership in the editor: editing a collaborator's element makes you a
 * co-owner, as part of the edit's own undo entry, so undoing every edit you
 * made to it removes you again (and redo puts you back).
 */
import {
  CREATOR_ID_KEY,
  CaptureUpdateAction,
  EDITOR_IDS_KEY,
  EDITOR_SEQS_KEY,
  newElementWith,
} from "@excalidraw/element";

import type {
  ExcalidrawElement,
  NonDeletedExcalidrawElement,
} from "@excalidraw/element/types";

import { actionChangeStrokeWidth } from "../actions/actionProperties";
import { prepareElementsForExport } from "../data";
import { Excalidraw } from "../index";
import { getCollaboratorVisibilityRows } from "../scene/visibility";

import { API } from "./helpers/api";
import { Keyboard } from "./helpers/ui";
import { act, render, unmountComponent } from "./test-utils";

import type { AppState } from "../types";

unmountComponent();

const h = window.h;

const stamp = <T extends ExcalidrawElement>(
  element: T,
  creatorId: string,
  editorIds?: string[],
) =>
  newElementWith(element as ExcalidrawElement, {
    customData: {
      [CREATOR_ID_KEY]: creatorId,
      ...(editorIds ? { [EDITOR_IDS_KEY]: editorIds } : {}),
    },
  }) as T;

const createRect = (id: string, x: number) =>
  API.createElement({ type: "rectangle", id, x, y: 0, width: 10 });

const get = (id: string) =>
  h.elements.find((el) => el.id === id)! as NonDeletedExcalidrawElement;
const editorIdsOf = (id: string) => get(id).customData?.[EDITOR_IDS_KEY];

/** sets the selection's stroke width (one undo entry) */
const edit = (strokeWidth: number) =>
  act(() => {
    h.app.actionManager.executeAction(
      actionChangeStrokeWidth,
      "ui",
      strokeWidth,
    );
  });
const widthOf = (id: string) => get(id).strokeWidth;

const collaborators = new Map([
  ["my-socket", { id: "me", username: "Me", isCurrentUser: true }],
  ["alice-socket", { id: "alice", username: "Alice" }],
]) as unknown as AppState["collaborators"];

beforeEach(async () => {
  await render(<Excalidraw handleKeyboardGlobally={true} />);
  act(() => {
    h.app.updateScene({
      elements: [
        stamp(createRect("alice-rect", 0), "alice"),
        stamp(createRect("me-rect", 40), "me"),
      ],
      collaborators,
      captureUpdate: CaptureUpdateAction.NEVER,
    });
    API.setAppState({
      collaboratorDirectory: new Map([
        ["me", { username: "Me", lastSeen: 1 }],
        ["alice", { username: "Alice", lastSeen: 1 }],
        ["carol", { username: "Carol", lastSeen: 1 }],
      ]),
    });
  });
});

describe("becoming a co-owner", () => {
  it("editing a collaborator's element adds me as a co-owner, keeping the creator", () => {
    API.setSelectedElements([get("alice-rect")]);
    edit(4);

    expect(widthOf("alice-rect")).toBe(4);
    expect(get("alice-rect").customData?.[CREATOR_ID_KEY]).toBe("alice");
    expect(editorIdsOf("alice-rect")).toEqual(["me"]);
  });

  it("selecting without editing doesn't", () => {
    API.setSelectedElements([get("alice-rect")]);
    expect(editorIdsOf("alice-rect")).toBeUndefined();
  });

  it("editing my own element doesn't add me as a co-owner", () => {
    API.setSelectedElements([get("me-rect")]);
    edit(4);
    expect(editorIdsOf("me-rect")).toBeUndefined();
  });

  it("editing it again doesn't add me twice", () => {
    API.setSelectedElements([get("alice-rect")]);
    edit(4);
    edit(5);
    expect(editorIdsOf("alice-rect")).toEqual(["me"]);
  });

  it("a co-owned element counts for each owner in the menu", () => {
    API.setSelectedElements([get("alice-rect")]);
    edit(4);
    const rows = getCollaboratorVisibilityRows(h.elements, h.state);
    const counts = Object.fromEntries(
      rows.inRoom.map((row) => [row.id, row.drawingsCount]),
    );
    expect(counts).toEqual({ me: 2, alice: 1 });
  });

  it("once I co-own it, locking its creator doesn't lock it for me", () => {
    API.setSelectedElements([get("alice-rect")]);
    edit(4);
    API.setAppState({ lockedCollaboratorIds: new Set(["alice"]) });
    expect(h.state.selectedElementIds["alice-rect"]).toBe(true);
  });

  it("without co-owning, locking its creator deselects it (unchanged)", () => {
    API.setSelectedElements([get("alice-rect")]);
    API.setAppState({ lockedCollaboratorIds: new Set(["alice"]) });
    expect(h.state.selectedElementIds["alice-rect"]).toBeUndefined();
  });
});

describe("undo / redo", () => {
  it("undoing my only edit removes me as a co-owner, redo adds me back", () => {
    API.setSelectedElements([get("alice-rect")]);
    const original = widthOf("alice-rect");
    edit(4);

    Keyboard.undo();
    expect(widthOf("alice-rect")).toBe(original);
    expect(editorIdsOf("alice-rect")).toEqual([]);
    // the removal is kept (with a newer counter) so stale copies lose
    expect(get("alice-rect").customData?.[EDITOR_SEQS_KEY]).toEqual({ me: 2 });

    Keyboard.redo();
    expect(widthOf("alice-rect")).toBe(4);
    expect(editorIdsOf("alice-rect")).toEqual(["me"]);
  });

  it("I stay a co-owner until ALL my edits to the element are undone", () => {
    API.setSelectedElements([get("alice-rect")]);
    const original = widthOf("alice-rect");
    edit(4);
    edit(5);

    Keyboard.undo();
    expect(widthOf("alice-rect")).toBe(4);
    expect(editorIdsOf("alice-rect")).toEqual(["me"]);

    Keyboard.undo();
    expect(widthOf("alice-rect")).toBe(original);
    expect(editorIdsOf("alice-rect")).toEqual([]);
  });

  it("undo keeps co-owners other clients added in the meantime", () => {
    API.setSelectedElements([get("alice-rect")]);
    const original = widthOf("alice-rect");
    edit(4);

    // carol edits it too (a remote update, not part of my history)
    act(() => {
      h.app.updateScene({
        elements: h.elements.map((el) =>
          el.id === "alice-rect"
            ? stamp(newElementWith(el, { y: 5 }), "alice", ["me", "carol"])
            : el,
        ),
        captureUpdate: CaptureUpdateAction.NEVER,
      });
    });

    Keyboard.undo();
    expect(widthOf("alice-rect")).toBe(original);
    expect(editorIdsOf("alice-rect")).toEqual(["carol"]);

    Keyboard.redo();
    expect(widthOf("alice-rect")).toBe(4);
    expect(editorIdsOf("alice-rect")).toEqual(["carol", "me"]);
  });

  it("undoing an unrelated edit doesn't touch my co-ownership", () => {
    API.setSelectedElements([get("alice-rect")]);
    edit(4);
    API.setSelectedElements([get("me-rect")]);
    const original = widthOf("me-rect");
    edit(6);

    Keyboard.undo();
    expect(widthOf("me-rect")).toBe(original);
    expect(editorIdsOf("alice-rect")).toEqual(["me"]);
  });
});

describe("visibility of a co-owned element (rendering, AC-B)", () => {
  // what the canvas draws: the jsdom viewport is 0x0, so ask the renderer
  // with an explicit viewport (same approach as collaboratorVisibility.test)
  const getRenderedIds = () =>
    h.app.renderer
      .getRenderableElements({
        zoom: h.state.zoom,
        offsetLeft: 0,
        offsetTop: 0,
        scrollX: 0,
        scrollY: 0,
        height: 1000,
        width: 1000,
        editingTextElement: h.state.editingTextElement,
        newElement: h.state.newElement,
        selectedElements: [],
        selectedElementsAreBeingDragged: false,
        frameToHighlight: null,
        hiddenCollaboratorIds: h.state.hiddenCollaboratorIds,
        collaboratorDirectory: h.state.collaboratorDirectory,
      })
      .visibleElements.map((el) => el.id)
      .sort();

  const getExportedIds = () =>
    prepareElementsForExport(h.elements, h.state, false)
      .exportedElements.map((el) => el.id)
      .sort();

  const setHidden = (ids: string[]) => {
    act(() => {
      API.setAppState({ hiddenCollaboratorIds: new Set(ids) });
    });
  };

  /** I edit alice's rectangle (a real edit, so I become a co-owner) */
  const coOwnAlicesRect = () => {
    API.setSelectedElements([get("alice-rect")]);
    edit(4);
    API.setSelectedElements([]);
  };

  /** a peer's update: carol's rectangle that dave has edited (co-owned) */
  const receiveCoOwnedRect = () => {
    act(() => {
      h.app.updateScene({
        elements: [
          ...h.elements,
          newElementWith(createRect("carol-rect", 80) as ExcalidrawElement, {
            customData: {
              [CREATOR_ID_KEY]: "carol",
              [EDITOR_IDS_KEY]: ["dave"],
              [EDITOR_SEQS_KEY]: { dave: 1 },
            },
          }),
        ],
        captureUpdate: CaptureUpdateAction.NEVER,
      });
      API.setAppState({
        collaboratorDirectory: new Map([
          ...h.state.collaboratorDirectory!,
          ["dave", { username: "Dave", lastSeen: 1 }],
        ]),
      });
    });
  };

  it("(control) without co-owners, hiding the creator hides the element", () => {
    expect(getRenderedIds()).toEqual(["alice-rect", "me-rect"]);
    setHidden(["alice"]);
    expect(getRenderedIds()).toEqual(["me-rect"]);
  });

  it("after I edit it, hiding its creator keeps it on my canvas and in exports", () => {
    coOwnAlicesRect();
    setHidden(["alice"]);
    expect(getRenderedIds()).toEqual(["alice-rect", "me-rect"]);
    expect(getExportedIds()).toEqual(["alice-rect", "me-rect"]);
  });

  it("it's hidden once every one of its co-owners is hidden", () => {
    coOwnAlicesRect();
    setHidden(["alice", "me"]);
    expect(getRenderedIds()).toEqual([]);
    expect(getExportedIds()).toEqual([]);
  });

  it("a peer's co-owned element stays visible while any co-owner is visible", () => {
    receiveCoOwnedRect();
    expect(getRenderedIds()).toContain("carol-rect");

    setHidden(["carol"]);
    expect(getRenderedIds()).toContain("carol-rect");

    setHidden(["dave"]);
    expect(getRenderedIds()).toContain("carol-rect");

    setHidden(["carol", "dave"]);
    expect(getRenderedIds()).not.toContain("carol-rect");
  });

  it("shows again as soon as one co-owner is shown again", () => {
    receiveCoOwnedRect();
    setHidden(["carol", "dave"]);
    expect(getRenderedIds()).not.toContain("carol-rect");
    setHidden(["carol"]);
    expect(getRenderedIds()).toContain("carol-rect");
  });
});

packages/element/src/__tests__/ownership.source:
/**
 * Issue #81 — unit tests for the pure interactivity rule and lock-list
 * transitions in `ownership.ts`. Expected values come from the acceptance
 * criteria in #81:
 *
 * - C: no interactivity without visibility (hidden → never interactive)
 * - H: my own drawings are never locked and always stay interactive
 * - A/B: locking / unlocking a bucket, Lock all, Unlock all
 */
import { arrayToMap } from "@excalidraw/common";

import { newElement, newTextElement } from "../newElement";
import {
  CREATOR_ID_KEY,
  UNKNOWN_CREATOR_ID,
  addLockedCollaborators,
  excludeNonInteractiveElements,
  getSelfCreatorId,
  isCollaboratorInteractive,
  isElementInteractive,
  toggleLockedCollaborator,
  unlockVisibleCollaborators,
} from "../ownership";

const createRect = (creatorId?: string) =>
  newElement({
    type: "rectangle",
    x: 0,
    y: 0,
    customData:
      creatorId === undefined ? undefined : { [CREATOR_ID_KEY]: creatorId },
  });

const sets = (hidden: string[] = [], locked: string[] = []) => ({
  hiddenCollaboratorIds: new Set(hidden),
  lockedCollaboratorIds: new Set(locked),
});

/** `collaborators` as the editor stores them, with "me" as the current user */
const collaborators = new Map([
  ["my-socket", { id: "me", isCurrentUser: true }],
  ["alice-socket", { id: "alice" }],
]);

describe("isCollaboratorInteractive (the interactivity rule)", () => {
  it("AC-A: a bucket that is neither hidden nor locked is interactive", () => {
    expect(isCollaboratorInteractive("alice", sets(), "me")).toBe(true);
  });

  it("AC-A: a locked, visible bucket is not interactive", () => {
    expect(isCollaboratorInteractive("alice", sets([], ["alice"]), "me")).toBe(
      false,
    );
  });

  it("AC-C: a hidden bucket is not interactive even if it isn't locked", () => {
    expect(isCollaboratorInteractive("alice", sets(["alice"]), "me")).toBe(
      false,
    );
  });

  it("AC-C: a hidden and locked bucket is not interactive", () => {
    expect(
      isCollaboratorInteractive("alice", sets(["alice"], ["alice"]), "me"),
    ).toBe(false);
  });

  it("AC-A: locking one bucket doesn't affect another", () => {
    expect(isCollaboratorInteractive("bob", sets([], ["alice"]), "me")).toBe(
      true,
    );
  });

  it("AC-H: my own bucket stays interactive even if it is in the lock list", () => {
    expect(isCollaboratorInteractive("me", sets([], ["me"]), "me")).toBe(true);
  });

  it("AC-C over AC-H: my own hidden bucket is not interactive (no interactivity without visibility)", () => {
    expect(isCollaboratorInteractive("me", sets(["me"]), "me")).toBe(false);
  });

  it("AC-A (misc): the miscellaneous bucket can be locked", () => {
    expect(
      isCollaboratorInteractive(
        UNKNOWN_CREATOR_ID,
        sets([], [UNKNOWN_CREATOR_ID]),
        "me",
      ),
    ).toBe(false);
  });

  it("AC-G: with no lock or visibility state (e.g. outside a room) everything is interactive", () => {
    expect(isCollaboratorInteractive("alice", {}, null)).toBe(true);
  });

  it("without a known self id, a locked bucket is still not interactive", () => {
    expect(isCollaboratorInteractive("alice", sets([], ["alice"]), null)).toBe(
      false,
    );
  });
});

describe("addLockedCollaborators", () => {
  it("AC-B: adds every given bucket to the lock list", () => {
    expect(
      [...addLockedCollaborators(new Set(), ["alice", "bob"], "me")].sort(),
    ).toEqual(["alice", "bob"]);
  });

  it("AC-B: keeps buckets that were already locked", () => {
    expect(
      [...addLockedCollaborators(new Set(["carol"]), ["alice"], "me")].sort(),
    ).toEqual(["alice", "carol"]);
  });

  it("AC-H: never adds me", () => {
    expect([
      ...addLockedCollaborators(new Set(), ["me", "alice"], "me"),
    ]).toEqual(["alice"]);
  });

  it("AC-G: doesn't mutate the current lock list (state is replaced, not edited)", () => {
    const locked = new Set(["carol"]);
    addLockedCollaborators(locked, ["alice"], "me");
    expect([...locked]).toEqual(["carol"]);
  });

  it("accepts a missing lock list", () => {
    expect([...addLockedCollaborators(undefined, ["alice"], null)]).toEqual([
      "alice",
    ]);
  });
});

describe("toggleLockedCollaborator", () => {
  it("AC-A: locks an unlocked, visible bucket", () => {
    expect([...toggleLockedCollaborator(sets(), "alice", "me")]).toEqual([
      "alice",
    ]);
  });

  it("AC-A: unlocks a locked, visible bucket", () => {
    expect([
      ...toggleLockedCollaborator(sets([], ["alice"]), "alice", "me"),
    ]).toEqual([]);
  });

  it("AC-A: leaves other buckets' locks unchanged", () => {
    expect(
      [...toggleLockedCollaborator(sets([], ["carol"]), "alice", "me")].sort(),
    ).toEqual(["alice", "carol"]);
  });

  it("AC-C: can't unlock a hidden bucket", () => {
    expect([
      ...toggleLockedCollaborator(sets(["alice"], ["alice"]), "alice", "me"),
    ]).toEqual(["alice"]);
  });

  it("AC-C: can't change the lock of a hidden bucket that isn't in the list", () => {
    expect([
      ...toggleLockedCollaborator(sets(["alice"]), "alice", "me"),
    ]).toEqual([]);
  });

  it("AC-H: can't lock me", () => {
    expect([...toggleLockedCollaborator(sets(), "me", "me")]).toEqual([]);
  });

  it("AC-G: doesn't mutate the current lock list", () => {
    const state = sets([], ["carol"]);
    toggleLockedCollaborator(state, "alice", "me");
    expect([...state.lockedCollaboratorIds]).toEqual(["carol"]);
  });
});

describe("unlockVisibleCollaborators (Unlock all)", () => {
  it("AC-B: unlocks every visible bucket", () => {
    expect([
      ...unlockVisibleCollaborators(sets([], ["alice", "bob"]), "me"),
    ]).toEqual([]);
  });

  it("AC-B + AC-C: hidden buckets stay locked, so they're still locked once shown", () => {
    expect([
      ...unlockVisibleCollaborators(sets(["bob"], ["alice", "bob"]), "me"),
    ]).toEqual(["bob"]);
  });

  it("AC-C: a hidden bucket that wasn't in the lock list ends up locked", () => {
    expect([...unlockVisibleCollaborators(sets(["bob"]), "me")]).toEqual([
      "bob",
    ]);
  });

  it("AC-H: never locks me, even when I'm hidden", () => {
    expect([...unlockVisibleCollaborators(sets(["me"]), "me")]).toEqual([]);
  });
});

describe("getSelfCreatorId", () => {
  it("AC-H: returns the current user's client id", () => {
    expect(getSelfCreatorId({ collaborators })).toBe("me");
  });

  it("returns null without a current user", () => {
    expect(
      getSelfCreatorId({ collaborators: new Map([["s", { id: "alice" }]]) }),
    ).toBe(null);
  });

  it("returns null when the current user has no client id yet", () => {
    expect(
      getSelfCreatorId({
        collaborators: new Map([["s", { isCurrentUser: true }]]),
      }),
    ).toBe(null);
  });

  it("returns null outside of a room (no collaborators)", () => {
    expect(getSelfCreatorId({})).toBe(null);
  });
});

describe("isElementInteractive", () => {
  const state = (hidden: string[] = [], locked: string[] = []) => ({
    ...sets(hidden, locked),
    collaborators,
  });

  it("AC-D: an element of a locked collaborator is not interactive", () => {
    const rect = createRect("alice");
    expect(
      isElementInteractive(rect, arrayToMap([rect]), state([], ["alice"])),
    ).toBe(false);
  });

  it("(control) an element of an unlocked collaborator is interactive", () => {
    const rect = createRect("alice");
    expect(isElementInteractive(rect, arrayToMap([rect]), state())).toBe(true);
  });

  it("AC-H: my own element stays interactive even if I'm in the lock list", () => {
    const rect = createRect("me");
    expect(
      isElementInteractive(rect, arrayToMap([rect]), state([], ["me"])),
    ).toBe(true);
  });

  it("AC-A (misc): an untagged element follows the miscellaneous bucket's lock", () => {
    const rect = createRect();
    expect(
      isElementInteractive(
        rect,
        arrayToMap([rect]),
        state([], [UNKNOWN_CREATOR_ID]),
      ),
    ).toBe(false);
  });

  it("AC-A (misc): a never-seen creator's element follows the miscellaneous bucket's lock", () => {
    const rect = createRect("dave");
    expect(
      isElementInteractive(rect, arrayToMap([rect]), {
        ...state([], [UNKNOWN_CREATOR_ID]),
        collaboratorDirectory: new Map([["alice", {}]]),
      }),
    ).toBe(false);
  });

  it("AC-D: a label follows its container's lock, not its own creator's", () => {
    const container = createRect("alice");
    const label = newTextElement({
      text: "label",
      x: 0,
      y: 0,
      containerId: container.id,
      customData: { [CREATOR_ID_KEY]: "me" },
    });
    expect(
      isElementInteractive(
        label,
        arrayToMap([container, label]),
        state([], ["alice"]),
      ),
    ).toBe(false);
  });
});

describe("excludeNonInteractiveElements", () => {
  const me = createRect("me");
  const alice = createRect("alice");
  const bob = createRect("bob");
  const elements = [me, alice, bob];

  it("returns the same array when nobody is hidden or locked", () => {
    expect(
      excludeNonInteractiveElements(elements, { ...sets(), collaborators }),
    ).toBe(elements);
  });

  it("AC-D: drops locked collaborators' elements", () => {
    expect(
      excludeNonInteractiveElements(elements, {
        ...sets([], ["alice"]),
        collaborators,
      }),
    ).toEqual([me, bob]);
  });

  it("AC-C: drops hidden collaborators' elements", () => {
    expect(
      excludeNonInteractiveElements(elements, {
        ...sets(["bob"]),
        collaborators,
      }),
    ).toEqual([me, alice]);
  });

  it("AC-H: keeps my own elements even if I'm in the lock list", () => {
    expect(
      excludeNonInteractiveElements(elements, {
        ...sets([], ["me", "alice", "bob"]),
        collaborators,
      }),
    ).toEqual([me]);
  });
});

